SELECT s.stay_id, COUNT(*) AS N, AVG(s.temperature) AS avg_temperature, MEDIAN(s.temperature) AS median_temperature, (percentile_cont(0.75) within GROUP (ORDER BY s.temperature) - percentile_cont(0.25) within GROUP (ORDER BY s.temperature)) AS interquartile_range, SUM(CASE WHEN s.temperature > 38.0 THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0) AS mi_rate FROM (SELECT p.subject_id, h.hadm_id, s.stay_id, l.value AS temperature FROM patients p JOIN icustays s ON p.subject_id = s.subject_id JOIN hospitals h ON h.subject_id = p.subject_id JOIN labevents l ON l.subject_id = p.subject_id AND l.hadm_id = h.hadm_id AND l.charttime BETWEEN s.intime AND s.outtime WHERE p.gender = 'F' AND p.anchor_age >= 81 AND p.anchor_age <= 91 AND l.itemid = 101 AND l.charttime BETWEEN s.intime AND s.outtime AND l.value BETWEEN 36.0 AND 37.9) AS s GROUP BY s.stay_id ORDER BY s.stay_id NULLS LAST;